input.command:
mkdir -p bootstrap && cd bootstrap
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
cat > variables.tf <<'EOF'
variable "region" {
  type        = string
  description = "AWS region the state bucket and its encryption key are created in."
  default     = "eu-north-1"
}

variable "state_bucket_name" {
  type        = string
  description = "Name of the S3 bucket that holds Terraform state. Must match the bucket in the backend block of the parent configuration."
  default     = "reports-tfstate-example"
}

variable "noncurrent_version_retention_days" {
  type        = number
  description = "Days a superseded state version is kept before it is deleted."
  default     = 90
}
EOF
cat > main.tf <<'EOF'
provider "aws" {
  region = var.region
}

resource "aws_kms_key" "state" {
  description             = "Encrypts Terraform state in ${var.state_bucket_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "state" {
  name          = "alias/${var.state_bucket_name}"
  target_key_id = aws_kms_key.state.key_id
}

resource "aws_s3_bucket" "state" {
  bucket = var.state_bucket_name
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-noncurrent-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_version_retention_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.state]
}

data "aws_iam_policy_document" "state_bucket" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > outputs.tf <<'EOF'
output "state_bucket" {
  description = "Name of the state bucket, for the bucket argument of the backend block."
  value       = aws_s3_bucket.state.id
}

output "state_kms_key_arn" {
  description = "ARN of the key that encrypts state. Principals that run plan and apply need kms:Decrypt, kms:Encrypt and kms:GenerateDataKey on it."
  value       = aws_kms_key.state.arn
}
EOF
cd ..
cat > backend.tf <<'EOF'
terraform {
  backend "s3" {
    bucket       = "reports-tfstate-example"
    key          = "reports/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    kms_key_id   = "alias/reports-tfstate-example"
    use_lockfile = true
  }
}
EOF
printf '*.tfstate\n*.tfstate.*\n*.tfplan\ntfplan\n.terraform/\ncrash.log\n*.auto.tfvars\nterraform.tfvars\n' > .gitignore
terraform fmt -recursive -check -diff
for d in . bootstrap; do (cd $d && terraform init -backend=false -input=false >/dev/null 2>&1; terraform validate); done; git status --short

